#!/usr/bin/env python3
from ta_emss import ta_emss
import time

CELL_ID_START = 5

if __name__ == "__main__":

    emss1 = ta_emss()
    emss1.setup_emss(user='vcu1', bts_ip='10.42.93.187', oam_ip='10.44.95.196', alias='cu1')
    mrbts_id = emss1.get_object_id('MRBTS')
    nrbts_id = emss1.get_object_id('NRBTS')

    # --- SETUP XTERM PARAMS ---
    print("Setting up...")
    emss1.xterm_setup(
        #--- XNAP PARAMS ---
        bts_xnap_ip_addr="10.255.14.144",
        gnbsim_ip_addr_begin="10.255.37.145",
        gnbsim_ip_addr_end="10.255.37.150",
        gnbsim_ip_addr_mask=25,
        gnbsim_eth_if="eth2",
        init_gnb_gnb_id=6003,
        init_gnb_mcc="555",
        init_gnb_mnc="10",
        # --- F1AP PARAMS ---
        bts_f1ap_ip_addr="10.255.11.25",
        vdusim_ip_addr_begin="10.255.37.5",
        vdusim_ip_addr_end="10.255.37.10",
        vdusim_ip_addr_mask=25,
        vdusim_eth_if="eth1",
        init_vdu_gnb_id=nrbts_id,
        init_vdu_amf_region_id=2,
        init_vdu_gnb_du_id=2,
        init_vdu_frequency_band=85,
        init_vdu_num_cells=3,
        init_vdu_cell_id_begin=CELL_ID_START,
        init_vdu_ul_arfcn=139800,
        init_vdu_dl_arfcn=145800,
        init_vdu_tac=7101,
        init_vdu_mcc="555",
        init_vdu_mnc="10",
        init_vdu_cell_dep_type='SA',
        # --- IPSEC PARAMS ---
        bts_oam_ip_addr="10.42.93.187",
        ipsec_xn=True,
        ipsec_f1=True,
        ipsec_policy_order_num_begin=2,
        # --- NGAP PARAMS ---
        # if a real AMF is active, there is no need to add a second one
        # --- XTERM OPTIONS ---
        verbose=True,
        debug=False
    )

    # --- CONFIGURE XNAP MOCS ---
    configure_mocs_command = []
    for gnb in emss1.xterm_get("gnbs"):
        moc_id = gnb['IP_ADDR'].split('.')[-1]
        configure_mocs_command.append({'MOC': 'XNLINK', 'ID': moc_id, 'cPlaneIpAddr': gnb['IP_ADDR']})
        configure_mocs_command.append(
            {'MOC': 'NRADJGNB', 'ID': moc_id, 'gNodeBId': str(gnb['GNB_ID']), "administrativeState": "Unlocked",
             'gnbPlmn': [{"mcc": gnb['MCC'], "mnc": gnb['MNC'], "mncLength": str(len(gnb['MNC']))}]})

    # --- CONFIGURE F1AP MOCS ---
    cell_id_start = CELL_ID_START
    dl_arfcn = emss1.xterm_get("vdus")[0]['DL_ARFCN']
    ul_arfcn = emss1.xterm_get("vdus")[0]['UL_ARFCN']

    for vdu in emss1.xterm_get("vdus"):
        du_id = vdu['GNB_DU_ID']
        vdu['DL_ARFCN'] = dl_arfcn
        vdu['UL_ARFCN'] = ul_arfcn
        cell_group_list = []
        for cell in vdu['SERVED_CELLS']:
            configure_mocs_command.append({'MOC': 'NRCELL', 'ID': str(cell_id_start),
                                           'a1MeashoEnabledSA': 'rsrp',
                                           'a1MeashoSsbRsrpSA': [{'a1HysteresishoSsbRsrpSA': 0,
                                                                  'a1ThresholdhoSsbRsrpSA': 60,
                                                                  'a1TimeToTriggerhoSsbRsrpSA': 'ms480'
                                                                  }],
                                           'a2MeashoEnabledSA': 'rsrp',
                                           'a2MeashoSsbRsrpSA': [{'a2HysteresishoSsbRsrpSA': '0',
                                                                  'a2ThresholdhoSsbRsrpSA': '34',
                                                                  'a2TimeToTriggerhoSsbRsrpSA': 'ms480'
                                                                  }],
                                           'cellReselectionPriority': '0',
                                           'cellDepType': vdu['CELL_DEP_TYPE'],
                                           'filterCoeffSsbRsrp': 'fc4',
                                           'filterCoeffSsbRsrq': 'fc4',
                                           'nrSysInfoProfileDN': f'MRBTS-{mrbts_id}/NRBTS-{nrbts_id}/NRSYSINFO_PROFILE-1',
                                           'trackingAreaDN': f'MRBTS-{mrbts_id}/NRBTS-{nrbts_id}/TRACKINGAREA-7101',
                                           'freqBandIndicatorNR': vdu['FREQUENCY_BAND'],
                                           'lcrId': str(cell_id_start),
                                           'physCellId': cell['PCI'],
                                           'allowUnsuppBcOrBcs': ['accept unknown band combinations'],
                                           'chBw': '50MHz',
                                           'drxProfileNrAnr': [{'drxControl': 'any', 'nrDrxDN': f'MRBTS-{mrbts_id}/NRBTS-{nrbts_id}/NRDRX-3'}],
                                           'rlfPsccTrigThresholdRsrp': '42',
                                           'a1MeashoEnabled': 'none',
                                           'a2MeashoEnabled': 'none',
                                           'cellTechnology': 'FDD',
                                           'ssPbchBlockPower': '10',
                                           'actDataForwardingForVoNr': 'deactivated',
                                           })
            configure_mocs_command.append({'MOC': 'NRCELL_FDD', 'ID': f'{cell_id_start}-1',
                                           'chBwDl': '5MHz',
                                           'chBwUl': '5MHz',
                                           'nrarfcnDl': dl_arfcn,
                                           'nrarfcnUl': ul_arfcn
                                           })
            configure_mocs_command.append({'MOC': 'NRCELLGRP', 'ID': str(cell_id_start),
                                           'scs': '15 KHz',
                                           'nrCellList': [cell_id_start]
                                           })
            cell_group_list.append(cell_id_start)
            cell_id_start += 1

        configure_mocs_command.append({'MOC': 'NRDU', 'ID': du_id,
                                       'actConnectedModeMobilityCA': 'true',
                                       'actInterNumerologyCa': 'true',
                                       'carrierAggregationSupportList': ['ca_Fr1Tdd_Any_Sa', 'ca_Fr1Tdd_Fdd_Sa', 'ca_Fr1Tdd_Sa'],
                                       'flexibleCAMode': 'ConfigurationIndependent',
                                       'gNbDuId': du_id,
                                       'gNbDuName': f'VDU_{du_id}',
                                       'refNrCellGroup': cell_group_list,
                                       'remoteDuIpAddr': vdu['IP_ADDR']},
                                      )
        dl_arfcn += 20
        ul_arfcn += 20
    emss1.configure_bts(configure_mocs_command, skip_np=False)
    time.sleep(15)

    # --- START F1AP AND XNAP SIMULATION ---
    print("Starting F1AP and XNAP ...")
    emss1.xterm_start(f1ap=True, xnap=True)

    time.sleep(100)

    print("CONFIGURE IPSEC")
    # --- ADD IPSEC CONFIG ---
    xnc_vcu_ip_addr = emss1.xterm_get("all")['BTS_XNAP_IP_ADDR']
    f1c_vcu_ip_addr = emss1.xterm_get("all")['BTS_F1AP_IP_ADDR']
    policy_order_number = emss1.xterm_get("all")['IPSEC_POLICY_ORDER_NUM_BEGIN']

    configure_ipsec_mocs_command = []

    configure_ipsec_mocs_command.append({'MOC': 'IPAPP', 'ID': '1-2-1'})
    configure_ipsec_mocs_command.append({'MOC': 'IPSECC', 'ID': '1-2-1-1',
                                         'authenticationScheme': 'PSK',
                                         'ipSecEnabled': 'true'})
    configure_ipsec_mocs_command.append({'MOC': 'IPSECP', 'ID': '1-2-1-1-1',
                                         'antiReplayWindowSize': 'SIZE_128',
                                         })
    moc_id = 1
    for moc_id, gnb in enumerate(emss1.xterm_get("gnbs"), start=1):
        configure_ipsec_mocs_command.append({'MOC': 'IKEP', 'ID': f'1-2-1-1-{moc_id}',
                                             'localTunnelEndpointDN': f'MRBTS-{mrbts_id}/TNLSVC-1/TNL-2/IPNO-1/IPIF-3/IPADDRESSV4-1',
                                             'remoteTunnelEndpoint': gnb['IP_ADDR']
                                             })
        configure_ipsec_mocs_command.append({'MOC': 'SECPOL', 'ID': f'1-2-1-1-{moc_id}',
                                             'ikePDN': f'MRBTS-{mrbts_id}/TNLSVC-1/TNL-2/IPAPP-1/IPSECC-1/IKEP-{moc_id}',
                                             'ipSecPDN': f'MRBTS-{mrbts_id}/TNLSVC-1/TNL-2/IPAPP-1/IPSECC-1/IPSECP-1',
                                             'policyOrderNumber': policy_order_number,
                                             'trafficSelectorList': [{'localIpAddress': xnc_vcu_ip_addr,
                                                                      'localIpPrefixLength': '32',
                                                                      'remoteIpAddress': gnb['IP_ADDR'],
                                                                      'remoteIpPrefixLength': '32'
                                                                      }]
                                             })
        policy_order_number += 1
        moc_id += 1

    for moc_id, vdu in enumerate(emss1.xterm_get("vdus"), start=moc_id):
        configure_ipsec_mocs_command.append({'MOC': 'IKEP', 'ID': f'1-2-1-1-{moc_id}',
                                             'localTunnelEndpointDN': f'MRBTS-{mrbts_id}/TNLSVC-1/TNL-2/IPNO-1/IPIF-2/IPADDRESSV4-1',
                                             'remoteTunnelEndpoint': vdu['IP_ADDR']
                                             })
        configure_ipsec_mocs_command.append({'MOC': 'SECPOL', 'ID': f'1-2-1-1-{moc_id}',
                                             'ikePDN': f'MRBTS-{mrbts_id}/TNLSVC-1/TNL-2/IPAPP-1/IPSECC-1/IKEP-{moc_id}',
                                             'ipSecPDN': f'MRBTS-{mrbts_id}/TNLSVC-1/TNL-2/IPAPP-1/IPSECC-1/IPSECP-1',
                                             'policyOrderNumber': policy_order_number,
                                             'trafficSelectorList': [{'localIpAddress': f1c_vcu_ip_addr,
                                                                      'localIpPrefixLength': '32',
                                                                      'remoteIpAddress': vdu['IP_ADDR'],
                                                                      'remoteIpPrefixLength': '32'
                                                                      }]
                                             })
        policy_order_number += 1

    emss1.configure_bts(configure_ipsec_mocs_command, skip_np=False)
    time.sleep(5)

    # --- BREAK SIMULATION ---
    while (k := input("Press 'q' to stop...")) != 'q':
        pass

    # --- DELETE PREVIOUSLY ADDED MOCS ---
    print("Deleting previously added NRDU, NRCELL, NRCELLGRP, XNLINK and NRADJGNB mocs")
    delete_moc_command = []
    number_of_vdus = len(emss1.xterm_get("vdus"))
    number_of_cell_per_vdu = len(emss1.xterm_get("vdus")[0]['SERVED_CELLS'])

    for vdu in emss1.xterm_get("vdus"):
        delete_moc_command.append({'DEL': 'NRDU', 'ID': vdu['GNB_DU_ID']})
    for moc_id in range(CELL_ID_START, CELL_ID_START + number_of_vdus * number_of_cell_per_vdu):
        delete_moc_command.append({'DEL': 'NRCELLGRP', 'ID': moc_id})
        delete_moc_command.append({'DEL': 'NRCELL', 'ID': moc_id})
    for gnb in emss1.xterm_get("gnbs"):
        delete_moc_command.append({'DEL': 'XNLINK', 'ID': gnb['IP_ADDR'].split('.')[-1]})
        delete_moc_command.append({'DEL': 'NRADJGNB', 'ID': gnb['IP_ADDR'].split('.')[-1]})
    emss1.configure_bts(delete_moc_command)

    # --- STOP XTERM ---
    print("Stopping xterm")
    emss1.xterm_teardown()
